                "hanzi": "看着卧病在床咳嗽不止的父亲，年轻的木兰在明亮的月光下暗自下定了坚定的决心。",
                "pinyin": "Kàn zhe wòbìng zài chuáng késou bùzhǐ de fùqīn, niánqīng de Mùlán zài míngliàng de yuèguāng xià ànzì xiàdìng le jiāndìng de juéxīn.",
