        "audioText": "唧唧复唧唧，木兰当户织，清脆的织布机声在安静的院子里回荡。忽然织布机的声音停了下来，只能听到木兰一声接一声长长的叹息。母亲走过来关切地轻声询问，木兰并不是在思念心上人，而是心中藏着沉重的心事。昨夜朝廷快马送来了紧急军帖，可汗大点兵，北方游牧骑兵正大举进犯边疆。官府颁布的征兵文书一共有整整十二卷，每一卷上面都赫然写着年迈父亲的名字。父亲年纪已经很大了，身上旧伤累累且常年多病，早已无法承受远征的万般辛苦。阿爷没有成年的长子可以顶替服役，而木兰也没有能够独当一面的健壮长兄。唯一的弟弟年纪还非常幼小，身量未长，甚至连一把普通的铁剑都握拿不稳。看着卧病在床咳嗽不止的父亲，年轻的木兰在明亮的月光下暗自下定了坚定的决心。她愿为市鞍马，从此替父出征，踏上保家卫国、充满生死考验的从军之路。"
