        "audioText": "东方刚刚泛起鱼肚白，木兰便悄悄换上便装，骑着小毛驴赶往城中最繁华的集市。她来到东市挑选了一匹神骏非凡的烈马，又来到西市配齐了坚实牢固的马鞍与鞍垫。接着木兰在南市选配了铜铸的精致辔头，在北市买下了一柄韧性十足的赶马长鞭。回到家中，木兰用粗布紧紧缠束胸脯，换上了威严的精铁铠甲和牛皮战靴。她把一头乌黑的长发高高扎成利落的男式发髻，扣上铁盔，宛如一位英姿飒爽的少年勇士。早晨辞别爹娘启程出发，父母站在村口泪眼婆娑，拉着战马的缰绳久久不愿松手。傍晚时分大军抵达了黄河岸边，夜宿在水势凶猛、乱石林立的黄河渡口边。她听不见爹娘呼唤女儿的温暖关怀，耳边只有黄河流水拍打着巨石奔腾咆哮的隆隆响声。夜风呼啸吹动着军营大旗，木兰合衣卧在行军帐篷中，望着摇曳的烛火默默握紧拳头。明日大军就要翻越黑山深入险境，她暗暗发誓一定要奋勇立功，活着重见爹娘容颜。"
