        "audioText": "辞别了汹涌澎湃的黄河，大军顶着刺骨晨风日夜兼程，向着燕山深处的黑山行进。暮色降临在荒凉陡峭的黑山头，四周枯草遍野，寸草不生，不见半点人烟。这里听不见父母亲昵温存的叮咛，只能听到塞外敌军胡骑在山谷间凄厉尖锐的悲鸣声。塞外的寒风狂暴地撕扯着军帐，卷起漫天沙石，打在铁甲上发出噼噼啪啪的声响。为了隐瞒女儿之身，木兰每晚都借故在最冷清的角落就寝，衣不解带，和衣而眠。军营白日的训练极其严苛，木兰苦练枪法与箭术，手臂常常被弓弦勒出一道道血痕。但她从不叫苦喊累，凭着坚韧的毅力，她很快在校场比武中百发百中，拔得头筹。老兵们见这位年轻新兵枪法精妙沉稳果决，都纷纷对其投以惊叹敬佩的目光。夜半轮班换防巡哨，木兰独自伫立在风雪之中，遥望南方长夜，心中充满对家的思念。朔气传金柝，寒光照铁衣，边塞的长夜无边无际，守护和平的誓言却如烈火般炽热。"
