        "audioText": "隆冬腊月，北风呼号，暴风雪铺天盖地而来，整个边境防线陷入了冰封之中。敌军骑兵趁着风雪遮蔽视线，纠集精锐企图暗中截断大军运送军粮的重要粮道。主帅派遣机警过人的木兰率领十人骑兵斥候小队，前往地形险恶的峡谷前线探查虚实。木兰趴伏在雪堆后仔细观察，从雪地上密集的马蹄深浅判断出敌军埋伏在鹰嘴岩后。她果断兵分两路，一路骑快马回营报信，自己则亲率五名精骑悄悄绕到敌军背后悬崖。待大军援兵赶到山谷时，木兰点燃狼烟信号，居高临下向敌阵猛烈放箭，引发敌军惊慌溃乱。前后夹击之下，这支来势汹汹的敌军伏兵被全歼在谷底，缴获战马两百余匹与全部军械。这是开战以来最漂亮的一场首战大捷，主帅在大帐中激动地拍案叫绝，重重嘉奖斥候队。木兰因智勇双全被当即破格提拔为统领两百勇士的年轻军官，正式名扬三军营垒。她把朝廷赏赐的金银全部分发给手下的负伤将士，将士们无不折服，誓愿死战报国。"
