        "audioText": "漫长残酷的边境战火断断续续持续了整整十年，岁月的风霜将木兰的面庞染上了坚毅之色。在这漫长的征途中，大军跨越万水千山，万里赴戎机，关山度若飞。无数英勇顽强的忠烈将士在刀光剑影中壮烈捐躯，木兰也经历了上百次九死一生的血腥恶战。每当两军在黄沙古道前线交锋时，木兰总是身先士卒，手握长枪策马奔驰在冲锋阵列最前端。她枪法若游龙探海，出神入化，敌军首领见其武艺非凡，皆惊呼其为天降神将而不敢轻易近前。然而无论战斗多么残酷激烈，木兰从不妄动杀戮，只要敌寇败退投降，她便下令严禁屠害俘虏。在一次遭遇伏击的险恶混战中，副将不幸坠马陷入重重重围，性命垂危，危在旦夕。木兰毫不犹豫拍马冲回重围，单骑连挑三名敌将，拼死将负伤的副将横搭在马鞍上安全救出。归营后她强忍着肩头被毒箭划伤的剧痛，独自在帐内拔箭敷药，从未向任何人吐露过半句娇弱。三军将士见木兰义薄云天、爱兵如子，皆发自肺腑地尊奉她为可托付生死的真正帅领。"
