        "audioText": "在战争第十年的决战时刻，敌军集结十万铁骑决死一搏，在大漠深处摆下了凶狠的龙蛇锁骨大阵。敌军阵中旌旗蔽日，杀气腾腾，狂风卷着血腥的沙尘扑面而来，局势千钧一发。木兰登上烽火高台勘察敌势，敏锐识破了敌军阵型外强中干、后方粮台防备空虚的致命破绽。她主动向主帅请缨，由主力部队在正面擂鼓列阵牵制敌军主力，自己则亲率轻骑千里奔袭敌军后路。深夜子时，木兰率三千精锐铁骑人衔枚、马裹蹄，如同幽灵般神速潜入敌营后方。一声令下，三千支带火的火箭呼啸划破黑夜，将敌军的粮仓与大帐点燃成滔天烈焰。敌军顿时自相践踏，大溃而逃，木兰纵马挥枪直取敌将中军，一枪刺落敌方大纛帅旗。正面大军见火起旗落，乘势发起总攻，十万敌骑全线崩溃，敌酋只得下马跪降。将军百战死，壮士十年归，十年苦战终迎和平，欢呼之声响彻了整座茫茫大漠。木兰勒马凝望初升的红日，眼中泛起激动的泪光，她终于可以卸下重甲重归故土了。"
