        "audioText": "战事平定后大军班师回朝，归来见天子，天子坐明堂，京城街道万人空巷夹道欢呼。巍峨宏伟的金銮大殿之上，香烟缭绕，金甲侍卫列队肃立，文武百官共同向凯旋英雄贺功。天子亲自翻开策勋录，策勋十二转，赏赐百千强，木兰的战功高居三军之首。皇帝见眼前的年轻将军英武不凡、双目明澈，心生大爱，当朝赐予黄金万两与锦缎千匹。可汗问所欲，欲加封木兰为正三品尚书郎，进入枢密中枢参与辅佐朝廷军国机务。在所有人眼里，这是一步登天、光宗耀祖的无上荣耀，百官无不向木兰投去艳羡目光。然而身披战甲的木兰却神情肃穆，双手合抱，恭敬地向天子长跪不起。木兰不用尚书郎，愿驰千里足，送儿还故乡，她清脆坚定的声音响彻金銮宝殿。她坦言自己从军只为替父尽孝、保全山河，如今战乱已止百姓安泰，唯一的愿望就是侍奉爹娘余生。天子与满朝文武听罢无不肃然起敬，深深感佩这位年轻勇将淡泊名利、至纯至孝的崇高风骨。"
