        "audioText": "天子不仅准许了木兰的请求，更特赐御马苑中最好的千里神驹，并派遣十二位军中战友一路护送其衣锦还乡。木兰在殿前三叩九拜叩谢皇恩，卸下了腰间御赐的金印，迈着轻快坚定的步伐走出了巍峨的金銮殿。出得城来，暖洋洋的春风拂过绿柳，清脆的鸟鸣声在田野间欢快地回荡。十二位同营战友骑在马上谈笑风生，赞叹着木兰在朝堂之上气度不凡的非凡气魄。一位年纪相仿的战友打趣笑道：“木兰兄弟，立下这等通天战功却不要官职，你回家到底想做些什么？”木兰轻轻扬起马鞭，眼中含笑答道：“自然是回归田园，织布种桑，伴随爹娘尽享天伦之乐。”战友们听了都哈哈大笑，只道他是想念故乡甘做闲人，却无人知晓她心中真正的秘密。骏马飞驰，沿途路过当年宿营的黄河渡口，如今岸边已是一派渔樵耕织、百姓安居乐业的和平景象。十年前别离时满目疮痍的风雪战场，今日终于换来了春回大地的万家灯火与祥和平安。木兰策马越过最后一道山梁，远远望见了故乡村庄那一缕缕熟悉的炊烟，热泪瞬间模糊了双眼。"
