        "audioText": "开我东阁门，坐我西阁床，木兰推开昔日内室的房门，坐在童年那张温暖熟悉的小木榻上。脱我战时袍，著我旧时裳，她轻轻解下一身刀痕累累的坚硬铁铠，小心地折叠整齐安放在衣箱底部。她从柜中取出一袭珍藏多年的淡粉色丝罗襦裙，换在身上，衣袂轻盈如云霞拂面。当窗理云鬓，对镜帖花黄，木兰端坐在梳妆台前，轻启妆奁，拿起那把光滑温润的红木角梳。她散开束了十二年之久的男式发髻，满头青丝如黑色瀑布般倾泻而下，散发出淡淡的幽香。木兰手法娴熟地为自己挽起端庄典雅的流云双髻，斜插上一支母亲留给她的精致翡翠金簪。她蘸了微润的金黄花粉，细心地在眉间额心贴上娇艳的花黄图案，更衬托出肤白胜雪、眉目如画。黄铜镜中的少女虽然眉宇间带着十年戎马沉淀下来的坚毅与英武，却毫无疑问是一位倾国倾城的美丽佳人。木兰整肃衣衫，深吸了一口气，带着自信而温柔的笑意，轻轻伸手拉开了闺房的雕花房门。明媚的春光倾泻在小院的石阶上，微风拂动着她粉色的裙摆，宛若一朵在战火洗礼后盛开的铿锵木兰花。"
