        "audioText": "出门看火伴，火伴皆惊忙，十二位在堂屋品茶等候的战友听到脚步声转过身来，瞬间目瞪口呆，如遭雷击。他们手里的青瓷茶碗差点摔在地上，一个个用力揉搓着自己的双眼，根本不敢相信眼前的奇迹。同行十二年，不知木兰是女郎，伙伴们面面相觑，舌桥不下，震惊得许久说不出半句话来。平日里最粗犷勇猛的黑脸校尉结结巴巴地问：“你……你难道当真就是与我们在尸山血海中斩将夺旗的花将军？”木兰看着昔日袍泽手足无措的滑稽模样，忍不住掩袖轻笑，银铃般动听的笑声回荡在宁静的小院中。她福身向众兄弟敛衽行礼，将自己当年如何瞒过朝廷代父从军的缘由如实相告。将士们听罢前因后果，无不被木兰惊天地泣鬼神的纯孝与无畏气概深深震撼。十二名浴血沙场的铁血汉子眼眶泛红，齐刷刷单膝跪地，向这位伟大的巾帼统帅献上最崇高的敬礼。木兰连忙上前将战友们一一扶起，农家小院里备齐了丰盛的美酒佳肴，众人开怀畅饮，欢歌笑语经久不息。战火褪去，战袍换红妆，花木兰用十二年青春洗尽铅华，成就了中华历史上最动人的英雄传奇。"
