        "audioText": "东胜神洲海外有一国土，名曰傲来国，国近大海，海中有一座钟灵毓秀的名山，唤作花果山。山顶正当中有一块开天辟地以来的仙石，每受天真地秀、日精月华，感之既久，遂有灵通之意。忽一日天崩地裂巨响轰鸣，仙石迸裂产下一枚石卵，遇风化作一个五官俱备、四肢皆全的石猴。那石猴生来便能行走跳跃，双目射出两道灼灼金光，直冲云霄，惊动了九天之上的凌霄宝殿。他在山中行走跳跃，食草木，饮涧泉，采山花，觅树果，与狼虫为伴，虎豹为群，快乐逍遥自在。群猴在山涧洗澡戏水，见那泉水滚滚奔流，便好奇说道：“不知这水从何处流出，谁能寻得源头？”众猴拍手齐声大喊：“哪一个有本事钻进瀑布寻得源头且不伤身体者，我们就拜他为大王！”话音未落，石猴高声应道：“我进去！我进去！”说罢闭上双眼，纵身往飞流直下的瀑布中猛力一跳。穿过奔腾的水幕，里面竟无半点水浪，原来是一座天然铁板天生桥，桥后掩映着一座洞天福地。只见石碣上明明白白刻着一行正楷大字：花果山福地，水帘洞洞天！"
