        "audioText": "石猴喜不自胜，急忙纵身跳出水帘，对洞外的万千猴群招手高呼：“大喜！大喜！里面别有洞天！”他向众猴手舞足蹈地描述道：“里面宽敞无比，有石锅石灶、石碗石盆、石床石凳，真乃天赐家当！”“更妙的是外面水流如帘垂挂，风雨不侵，正是我们千秋万代安家落户的绝妙去处！”众猴听得心花怒放，个个争先恐后跟着石猴纵身往里跳，齐齐穿过水瀑进入了水帘洞内。猴群进洞后抢盆夺碗，占灶争床，欢呼打闹，不知疲倦地搬弄玩耍了好半天。石猴端坐于正当中的石座之上，正色说道：“列位曾言，谁能进来寻得源头便拜谁为王，如今我引尔等安居，何不拜我？”众猴听罢恍然顿悟，当即敛容整队，依齿序排班，齐齐朝石猴稽首长拜，高呼：“千岁大王！”自此石猴高登王位，遂隐去“石”字，自称“美猴王”，统领花果山万千飞禽走兽。美猴王分派职务，立四老猴为健将，带领众猴朝游花果山，夜宿水帘洞，不入人间纷争，不服阎王管辖。花果山春暖花开，水帘洞歌舞升平，仙猴在这世外桃源度过了三百余年无忧无虑的神仙岁月。"
