        "audioText": "一日宴乐正欢，美猴王忽然堕泪忧虑，感叹生老病死人生无常，暗自忧心百年后难逃阎王之手。通臂猿猴进前献策道：“唯有佛、仙、神圣三者可超脱轮回，躲过阎王管辖，长生不老，寿与天齐。”猴王闻言满心欢喜，当下决意云游海角天涯，访求仙道，以求长生不死之神术。次日他扎就一具坚实松木木筏，带上鲜果干粮，独自撑篙泛海，随波漂流。他飘洋过海历经十数年艰险跋涉，访遍南赡部洲，终于来到了西牛贺洲的地界。忽闻山林深处传来一阵悠扬古朴的樵夫对唱，歌词玄妙深奥，满是清心寡欲之道。猴王上前诚心问路，樵夫指点道：“不远处的灵台方寸山中，有位斜月三星洞的菩提祖师，正传授无上道法。”猴王喜出望外，急趋步前行，只见翠柏幽竹掩映着松篁洞门，烟霞散彩，祥光四溢，真乃神仙洞府！他进得洞中，见祖师端坐瑶台，仙气浩然，连忙恭敬倒身下拜，磕头不止乞求收录门下。祖师问其姓名来由，石猴答言天地生成无姓，祖师微笑道：“你就随猢狲之猢去兽旁，赐姓为孙，法名唤作‘悟空’！”"
