        "audioText": "美猴王学道归来花果山，诛灭混世魔王，整顿群猴，操演武艺，却苦于手中缺少一柄称心应手的神兵利刃。通背猿猴进言道：“大王既有通天之能，我们水帘洞铁板桥下直通东海龙宫，何不下海寻老龙王求件兵器？”悟空大喜，使个避水诀，跳出水帘，一个猛子扎入万丈波涛之下，如履平地般来到东海水晶宫门前。东海龙王敖广闻知是得道仙邻到访，慌忙率领虾兵蟹将出宫迎接，奉入金殿奉为上宾献茶。悟空直言来意：“闻老邻居水晶宫奇珍异宝无数，特来求借一件趁手兵刃操演防身。”龙王不好推脱，命鳜都督抬出一柄三千六百斤重的大捍刀，悟空接在手中随手舞了个花，嫌弃道：“太轻！太轻！”龙王复令鳝力士与鳖总兵抬出一杆七千二百斤重的九股叉，悟空拿在手里掂了一掂，依旧摇头：“轻得像根草棒！”龙王惊恐，又令人抬出一柄重达七千二百斤的方天画戟，悟空在殿中抡舞得风声呼呼，仍嫌不称手。龙婆与龙女在后屏急劝龙王道：“大王，海底海藏中有一块天河定海神珍铁，连日来霞光万道，莫非正该归他？”龙王无奈，只得引领悟空来到深海海藏之处，只见中央矗立着一根金光灿烂、粗若水缸的大铁柱！"
