        "audioText": "悟空上前抚摸这根神柱，只见铁柱两头套着两个金箍，正中央刻着金光闪闪的一行篆文。上面明明白白镌刻着八个大字：“如意金箍棒，重一万三千五百斤”！悟空心中大喜，自言自语道：“要是再细些、再短些，拿在手中就更为合意趁手了！”奇迹骤现，那神棒竟通人性，瞬间化作碗口粗细、丈二长短，金光流转，熠熠生辉！悟空拔出神棒握在掌中，大喜喊道：“再小！再小！”，神棒应声缩成一根绣花针般纤细，被他顺手塞入耳中藏纳！得此神珍，悟空喜心翻倒，但转念一想，又向龙王索求一身相配的行头披挂。敖广无奈撞响铁钟金鼓，唤齐南海、西海、北海三位龙王齐聚东海，合力献上重宝。南海龙王奉上“凤翅紫金冠”，西海龙王献上“锁子黄金甲”，北海龙王呈上“藕丝步云履”。悟空当殿穿戴齐备，头戴金冠，身披金甲，脚踏云履，手绰金箍棒，一路威风凛凛打出水晶宫。四海龙王两股战战，又恨又怕，当即具表向九天金銮殿之上的玉皇大帝飞本告御状！"
