        "audioText": "玉帝准奏命工部在蟠桃园右侧修建齐天大圣府，设安齐、宁神二司侍奉悟空。悟空每日在天宫游手好闲四处结交，玉帝唯恐他生事，命他掌管王母娘娘的蟠桃园。悟空欣然领命巡视桃园，只见万株仙桃红熟扑鼻，硕果累累，令人垂涎三尺。土地神禀告：“园前株三千年一熟人食成仙，中株六千年一熟长生不老，后株九千年一熟与天地齐寿。”悟空心中暗喜，自此每三两日便设法脱身独留园中，脱下冠服攀上树梢尽情大嚼。时逢王母娘娘设蟠桃胜会，七衣仙女提花篮进园采摘，却见仙桃尽被神猴吃光。仙女追寻中惊动树上酣睡的悟空，悟空问及胜会邀请各路神仙，唯独没有请他齐天大圣。悟空勃然大怒，念动真言念声“定”，施法定住七衣仙女，驾筋斗云直奔瑶池宝阁。瑶池仙境琼浆玉液香气扑鼻，悟空趁众仙童未至，变出瞌睡虫将造酒仙官尽皆催眠。悟空放开肚腹痛饮百味琼浆，大嚼龙肝凤髓珍馐佳肴，醉眼朦胧间东倒西歪。"
