        "audioText": "悟空暗想天条森严自己闯下泼天大祸，借着酒意摇摇晃晃欲回齐天府，却误入兜率宫。兜率宫中太上老君正与燃灯古佛在三层高阁讲道，丹房空无一人，丹灶旁排列数葫芦金丹。悟空欢喜叫道：“此乃仙家至宝！老孙正欲炼丹，今日撞着机缘，正好受用！”悟空将葫芦倾倒口中，如吃炒豆般把太上老君五葫芦九转金丹尽数吞入腹中。金丹入腹酒意渐消，悟空猛然清醒：“这场大祸非同小可，玉帝若知，安肯轻饶？”悟空当即施展隐身法，冲出西天门，一路按落筋斗云风驰电掣奔回花果山。瑶池之上狼藉一片，七仙女解咒哭诉，太上老君奏报失丹，玉帝震怒拍案而起。天皇大帝颁下法旨，命四大天王、二十八宿、九曜星官并十万天兵布下天罗地网。十八架天罗地网将花果山围得水泄不通，黑云压顶，杀声震天，日月无光。悟空率领七十二洞妖王挺身抗敌，手挥金箍棒独战九曜星官，毫无惧色杀声裂石！"
