        "audioText": "观音菩萨举荐二郎显圣真君下界擒妖，二郎神率梅山六兄弟与哮天犬赶赴花果山。悟空与二郎神各展神通大战三百回合，二郎化身飞禽，悟空化为水族，七十二般变化奇招迭出。太上老君在南天门凭栏观战，自袖中掷出至宝金刚琢，不偏不倚正中悟空天灵盖。悟空跌了一跤翻身爬起，哮天犬扑上咬住腿肚，梅山六兄弟一拥而上将其用勾刀穿琵琶骨绳捆索绑。妖猴押解斩妖台，刀砍斧剁不能伤其分毫，雷轰火烧亦难损他半根毫毛。太上老君奏道：“此猴偷吃了蟠桃、御酒，又吃了老道五葫芦金丹，已炼成金刚不坏之身。”玉帝准老君所请，将悟空推入兜率宫八卦炉中，用文武六丁神火煅炼七七四十九日。悟空钻入乾宫巽位风口之中，虽无大火烘烤，却被浓烟熏得双眼通红，炼就了一双“火眼金睛”。四十九日开炉之期已满，道童方揭开炉盖，悟空自烟火中纵身跳出，一脚蹬翻八卦炉。悟空手持金箍棒怒发如狂，一路直打到通明殿外、凌霄宝殿前，众天神无一人能当其锋芒！"
