        "audioText": "为使丈夫展其抱负独立立业，白素贞出资在镇江开设了一间药铺，取名“保安堂”。许仙坐堂行医把脉诊病，素贞精通岐黄之术在幕后配制奇药，保安堂名声渐起门庭若市。夫妻二人悬壶济世乐善好施，凡遇家贫无钱抓药之百姓，皆免除诊费倾囊相助。那年盛夏江南瘟疫大流行，无数百姓高烧不退吐泻不止，城中各家医馆皆束手无策。白素贞悲悯苍生受难，悄然施展千年法力凝聚仙露，研制出解毒驱疫的神效汤药。保安堂在门前支起三口大铁锅，日夜熬药，向全城百姓免费分发驱毒良方。患者服药之后往往不出三日即霍然而愈，镇江城内疫病遂告平息，全城百姓莫不称颂许善人。然而保安堂的名声远播，却招来了金山寺方丈法海和尚更深的戒备与敌意。法海自诩替天行道降妖除魔，固执地认定人妖殊途不可共存，决意伺机拆散这段因缘。一年一度的五月初五端午佳节转眼即至，一场打破平静的惊天危机正悄然逼近……"
