        "audioText": "端午节前夕，许仙依俗前往金山寺进香祈福，在宝殿前巧遇法海方丈迎面而来。法海打量许仙片刻，叹息道：“施主眉宇间缠绕浓重妖气，近来必与异类精怪同枕共眠！”许仙闻言勃然色变，不悦反驳：“我妻白氏知书达礼乐善济世，乃世间难寻之贤妻，长老休得污蔑！”法海冷笑道：“妖孽善于变化迷惑凡心，你肉眼凡胎，安知枕边之人是千年蛇精？”许仙心中虽不肯信，但见老僧神情笃定严峻，不由得脊背发凉，心生一丝疑忌波澜。法海自袖中取出雄黄一包递与许仙：“明日端午正午，只需劝她饮下雄黄宝酒，真假虚实自然分明。”许仙魂不守舍怀揣雄黄下山回家，素贞见丈夫面带愁容神色慌张，关切询问缘由。许仙强作镇定支吾掩饰，只说寺中香客拥挤略感疲惫，将雄黄暗自藏于药柜之中。小青向来嗅觉敏锐，警觉察觉到空气中隐隐带有寺院檀香与伏魔咒符之气息。她私下警告素贞当心法海施诡计，素贞却深信夫妻恩重如山，断不疑许仙会加害自己。"
