        "audioText": "五月初五端午正日，家家户户插艾叶悬菖蒲，雄黄酒香弥漫整个镇江古城。白素贞因已怀有身孕法力大减，蛇性畏惧雄黄天性难抗，特命小青前往山林避难。许仙在内室摆下精致酒菜，手捧两盏泛着金黄光芒的雄黄酒，满脸堆笑迎向素贞。许仙殷勤劝道：“娘子，今日佳节饮此雄黄酒，既能避瘟驱邪，又能保佑腹中胎儿平安。”素贞面露难色几番推辞，见丈夫神情执着充满试探之意，唯恐推脱惹起猜疑，便强忍不适一饮而尽。烈酒入喉如烈火焚心，千年道行瞬间紊乱，素贞腹痛如绞头晕目眩，跌跌撞撞奔向罗帐床榻。她用最后神识掩拢床幔，呻吟叮嘱：“官人快去外室烹煮醒酒酸汤，千万不可掀帐看我！”许仙慌忙奔至灶房煮好醒酒汤，端着热汤回房呼唤，床幔内却一片死寂杳无声息。许仙心焦如焚，顾不得娘子嘱咐，颤抖着伸手一把撩开了锦绣红罗帐。定睛看去，床上哪里有什么如花娇妻，赫然盘踞着一条碗口粗细、通体雪白的万年巨蟒！"
