        "audioText": "金山寺激战之际，许仙趁混乱之隙从后山悬崖系绳缒下，拼尽全力逃出寺院。他沿路乞讨风餐露宿赶回杭州，走到断桥边时已衣衫褴褛鞋履穿洞，步履蹒跚。桥头垂柳之下，许仙猛然看见白素贞倚在青石上抚腹喘息，小青手握寒剑怒目相向。小青见许仙现身，怒火中烧拔剑直刺而来：“负心汉！我姐姐为你闯昆仑盗仙草，险些丧命金山，你还有脸回来！”素贞拼尽残力推开青锋，用身躯护住许仙：“青儿住手！夫妻一场，纵是万劫不复，亦是妾身甘愿！”许仙闻言双膝跪倒在地，泪如雨下向二女磕头谢罪，倾吐心中从未改变之真情。许仙哭道：“娘子！我肉眼凡胎受老僧蛊惑，但你待我恩重如山情深似海，纵是蛇仙，许仙亦誓死相随！”见丈夫字字发自肺腑悔恨交加，小青长叹一声抛剑入鞘，素贞与许仙在断桥烟雨中相拥痛哭。历经水火浩劫的夫妻二人破镜重圆，回到姐姐家中暂住，数月后素贞顺利诞下一名白胖男婴。许仙为儿子取名许仕林，夫妇二人抱着襁褓娇儿，满屋欢声笑语，仿佛一切灾厄皆已烟消云散。"
